add_action( 'wp_footer', 'perfectpixel_special_offer_popup' );

function perfectpixel_special_offer_popup() {
	if ( function_exists( 'is_cart' ) && ( is_cart() || is_checkout() ) ) {
		return;
	}
	$url = trim( '{{offer_popup_url}}' );
