	<div class="perfectpixel-offer" role="dialog" aria-labelledby="perfectpixel-offer-title" hidden style="position:fixed;right:20px;bottom:20px;z-index:99998;max-width:320px;width:calc(100% - 40px);background:#fff;color:#1d2327;border-radius:6px;box-shadow:0 6px 24px rgba(0,0,0,.2);padding:1.1em 1.2em">
		<button type="button" class="perfectpixel-offer-close" aria-label="<?php echo esc_attr( '{{offer_popup_close_label}}' ); ?>" style="position:absolute;top:.3em;right:.4em;border:0;background:none;font-size:1.4em;line-height:1;cursor:pointer;color:inherit">&times;</button>
		<strong id="perfectpixel-offer-title" style="display:block;font-size:1.1em;margin:0 1.2em .4em 0"><?php echo esc_html( '{{offer_popup_title}}' ); ?></strong>
		<p style="margin:0 0 .8em"><?php echo esc_html( '{{offer_popup_text}}' ); ?></p>
		<?php if ( '' !== $url ) : ?>
			<a class="perfectpixel-offer-button" href="<?php echo esc_url( $url ); ?>" style="display:inline-block;padding:.5em 1em;border-radius:4px;background:#1d2327;color:#fff;text-decoration:none"><?php echo esc_html( '{{offer_popup_button}}' ); ?></a>
		<?php endif; ?>
	</div>
	<script>
	( function ( delay, days ) {
		var box = document.querySelector( '.perfectpixel-offer' );
		var key = 'perfectpixel_offer_hidden_until';
		if ( ! box ) {
			return;
		}
		try {
			if ( Number( window.localStorage.getItem( key ) ) > Date.now() ) {
				return;
			}
		} catch ( e ) {}
		var close = function () {
			box.hidden = true;
			try {
				window.localStorage.setItem( key, String( Date.now() + days * 86400000 ) );
			} catch ( e ) {}
		};
		box.querySelector( '.perfectpixel-offer-close' ).addEventListener( 'click', close );
		var button = box.querySelector( '.perfectpixel-offer-button' );
		if ( button ) {
			button.addEventListener( 'click', close );
		}
		document.addEventListener( 'keydown', function ( event ) {
			if ( 'Escape' === event.key && ! box.hidden ) {
				close();
			}
		} );
		setTimeout( function () {
			box.hidden = false;
		}, delay * 1000 );
	} )( <?php echo max( 0, (int) '{{offer_popup_delay}}' ); ?>, <?php echo max( 0, (int) '{{offer_popup_hide_days}}' ); ?> );
	</script>
	<?php
}
